/* =========================================================================
   COFRE — DESIGN TOKENS, THEME 1 (light/cream — the original identity)
   and THEME 2 (dark navy + gold — premium). C/TIER_COLORS/glass/gradients
   are `let` bindings, not `const` — switching themes reassigns them, and
   since every component reads these as plain free variables at render time
   (not via props or context), a single state change + re-render of the
   whole tree is all it takes for every screen to pick up the new values.
   No extra network requests, no new component tree — just swapped colors
   and (for the vault art) swapped image constants.
   ========================================================================= */
const THEME_CLEAN = {
  bgDeep: "#F3F1EA", bgNavy: "#F0F2ED", bgBlue: "#EAF0EE",
  surface1: "#FFFFFF", surface2: "#F1FAF9",
  strokeSoft: "rgba(20,41,63,0.09)", strokeActive: "rgba(6,164,175,0.45)",
  blueElectric: "#06A4AF", cyan: "#3FC1C9", violet: "#497CE6",
  green: "#058266", gold: "#E8A93D", goldLight: "#FBD780", amber: "#A3661B",
  danger: "#E1544B", text1: "#14293F", text2: "#5B6472", text3: "#96A0AC",
};

// Same black/gold vault art as Black, but a light neutral shell — sits
// between Clean and Black in contrast.
const THEME_SOFT = {
  bgDeep: "#F2F3F5", bgNavy: "#F4F5F7", bgBlue: "#F0F1F3",
  surface1: "#FFFFFF", surface2: "#F6F7F9",
  strokeSoft: "rgba(24,28,36,0.08)", strokeActive: "rgba(180,138,44,0.4)",
  blueElectric: "#4C6FE0", cyan: "#4B9CB0", violet: "#7C6CD8",
  green: "#1F9C74", gold: "#C08A2C", goldLight: "#E8C87A", amber: "#8C5E1F",
  danger: "#D14A42", text1: "#20242C", text2: "#565C68", text3: "#8B93A0",
};

const THEME_BLACK = {
  bgDeep: "#05080F", bgNavy: "#070B15", bgBlue: "#03050A",
  surface1: "#111A2E", surface2: "#0C1424",
  strokeSoft: "rgba(232,178,61,0.16)", strokeActive: "rgba(232,178,61,0.5)",
  blueElectric: "#4C7EF0", cyan: "#4FC7D6", violet: "#8B7CF0",
  green: "#2ECC8F", gold: "#E3B23D", goldLight: "#F6D98A", amber: "#C98A2B",
  danger: "#F16B63", text1: "#F5EFDD", text2: "#B7BECB", text3: "#7D8698",
};

let THEME_NAME = "clean";
let C = { ...THEME_CLEAN };
let TIER_COLORS = [C.blueElectric, C.cyan, C.violet, C.gold];
let bgGradient = "";
let glass = {};
let glassActive = {};
let ctaGradient = {};
let progressGradient = {};
let premiumGradient = {};

function recomputeThemeDerivedStyles() {
  if (THEME_NAME === "black") {
    bgGradient = `radial-gradient(120% 60% at 15% -10%, rgba(76,126,240,0.10) 0%, rgba(76,126,240,0) 55%),
   radial-gradient(120% 60% at 90% 0%, rgba(227,178,61,0.10) 0%, rgba(227,178,61,0) 55%),
   linear-gradient(180deg, ${C.bgDeep} 0%, #080D18 45%, ${C.bgBlue} 100%)`;
    glass = { background: C.surface1, border: `1px solid ${C.strokeSoft}`, boxShadow: "0 1px 0 rgba(255,255,255,0.03) inset, 0 14px 28px -18px rgba(0,0,0,0.55)", borderRadius: 18 };
    glassActive = { ...glass, background: C.surface2, border: `1px solid ${C.strokeActive}`, boxShadow: `0 0 0 1px rgba(227,178,61,0.16), 0 14px 28px -16px rgba(227,178,61,0.3)` };
    ctaGradient = { backgroundImage: `linear-gradient(90deg, #C98A2B 0%, #E3B23D 100%)` };
    progressGradient = { backgroundImage: `linear-gradient(90deg, #1B2947 0%, #E3B23D 100%)` };
  } else if (THEME_NAME === "soft") {
    // Light gray shell, same radial-tint recipe as Clean/Black (subtle blue
    // top-left, subtle gold top-right) but dialed way down — "leve" — over
    // a lighter gray base so the black/gold vault art pops without a flat,
    // colorless backdrop.
    bgGradient = `radial-gradient(120% 60% at 15% -10%, rgba(76,111,224,0.05) 0%, rgba(76,111,224,0) 55%),
   radial-gradient(120% 60% at 90% 0%, rgba(192,138,44,0.06) 0%, rgba(192,138,44,0) 55%),
   linear-gradient(180deg, ${C.bgDeep} 0%, #E9EAED 55%, ${C.bgBlue} 100%)`;
    glass = { background: C.surface1, border: `1px solid ${C.strokeSoft}`, boxShadow: "0 1px 0 rgba(255,255,255,0.7) inset, 0 14px 28px -18px rgba(20,24,31,0.14)", borderRadius: 18 };
    glassActive = { ...glass, background: C.surface2, border: `1px solid ${C.strokeActive}`, boxShadow: `0 0 0 1px rgba(180,138,44,0.16), 0 14px 28px -16px rgba(180,138,44,0.24)` };
    ctaGradient = { backgroundImage: `linear-gradient(90deg, #8C5E1F 0%, #C9962F 100%)` };
    progressGradient = { backgroundImage: `linear-gradient(90deg, #3A3F4A 0%, #C08A2C 100%)` };
  } else {
    bgGradient = `radial-gradient(120% 60% at 15% -10%, rgba(6,164,175,0.08) 0%, rgba(6,164,175,0) 55%),
   radial-gradient(120% 60% at 90% 0%, rgba(232,169,61,0.08) 0%, rgba(232,169,61,0) 55%),
   linear-gradient(180deg, ${C.bgDeep} 0%, #F0F2ED 45%, ${C.bgBlue} 100%)`;
    glass = { background: C.surface1, border: `1px solid ${C.strokeSoft}`, boxShadow: "0 1px 0 rgba(255,255,255,0.6) inset, 0 14px 28px -18px rgba(20,41,63,0.16)", borderRadius: 18 };
    glassActive = { ...glass, background: C.surface2, border: `1px solid ${C.strokeActive}`, boxShadow: `0 0 0 1px rgba(6,164,175,0.12), 0 14px 28px -16px rgba(6,164,175,0.28)` };
    ctaGradient = { backgroundImage: `linear-gradient(90deg, #06A4AF 0%, #497CE6 100%)` };
    progressGradient = { backgroundImage: `linear-gradient(90deg, #1F3A5F 0%, #E8A93D 100%)` };
  }

  premiumGradient = { backgroundImage: `linear-gradient(90deg, #A3661B 0%, #F0C368 50%, #A3661B 100%)` };
}

// Called once at App() render — cheap object reassignment, safe to run
// unconditionally on every render. "Soft" reuses the exact same black/gold
// vault art as "Black" — only the shell around it changes; "Clean" is the
// only one with its own (light) vault render.
function applyTheme(name) {
  THEME_NAME = name;
  C = name === "black" ? { ...THEME_BLACK } : name === "soft" ? { ...THEME_SOFT } : { ...THEME_CLEAN };
  TIER_COLORS = [C.blueElectric, C.cyan, C.violet, C.gold];
  VAULT_IMG = name === "clean" ? VAULT_IMG_LIGHT : VAULT_IMG_DARK;
  VAULT_OPEN_IMG = name === "clean" ? VAULT_OPEN_IMG_LIGHT : VAULT_OPEN_IMG_DARK;
  recomputeThemeDerivedStyles();
}
recomputeThemeDerivedStyles();

/* Small helper so text sizes are always inline styles (no arbitrary Tailwind
   classes — this sandbox ships a fixed, pre-built stylesheet with no JIT
   compiler, so classes like text-[13px] or w-[108px] silently produce no
   CSS at all). Every custom pixel value in this file goes through style={}. */
const fs_ = (px, extra) => ({ fontSize: px, ...extra });

