// Approximate annual yields used only to illustrate the difference between
// wallets — matches the scenarios already shown in the Patrimônio screen.
const WALLET_RATES = { poupanca: 0.07, cdb: 0.114, tesouro: 0.11, rf: 0.102, reserva: 0.08, casa: 0, outro: 0 };
const PROJECTION_MONTHS = 14; // same horizon used in the Patrimônio forecast

function projectGain(amount, annualRate, months = PROJECTION_MONTHS) {
  const r = annualRate / 12;
  return Math.round(amount * (Math.pow(1 + r, months) - 1));
}

const BEST_WALLET_ID = Object.entries(WALLET_RATES).reduce((best, [id, r]) => (r > (WALLET_RATES[best] ?? -1) ? id : best), "poupanca");

