/* =========================================================================
   SCREEN: COFRE MATCH™ — enter an amount you can save today, the app finds
   a combination of available numbers that adds up to it (heuristic, per
   PRODUCT_RULES.md: "subset-sum limitado com heurísticas e priorização de
   2–6 tiles"), then protects all of them in one confirmation.
   ========================================================================= */
function findMatchCombo(availableNumbers, target) {
  const sortedDesc = [...availableNumbers].sort((a, b) => b - a);

  // Compact match: try to land on (or very near) the target using just 2–6
  // tiles, largest first — reads nicer when it's feasible.
  const greedyWithCap = (maxTiles) => {
    const combo = [];
    let sum = 0;
    for (let i = 0; i < sortedDesc.length && combo.length < maxTiles; i++) {
      if (sum + sortedDesc[i] <= target) { combo.push(sortedDesc[i]); sum += sortedDesc[i]; }
      if (sum === target) break;
    }
    return { combo, sum };
  };

  // Unlimited fallback: keeps taking the largest number that still fits,
  // with no tile-count ceiling — needed whenever the target is bigger than
  // any 2–6 tile combo could ever reach (e.g. a large amount against small
  // remaining numbers). This is what actually guarantees the result lands
  // close to what the person typed, regardless of vault size.
  const greedyUnlimited = () => {
    const combo = [];
    let sum = 0;
    for (const num of sortedDesc) {
      if (sum + num <= target) { combo.push(num); sum += num; }
      if (sum === target) break;
    }
    return { combo, sum };
  };

  let best = { combo: [], sum: 0 };
  for (let maxTiles = 2; maxTiles <= 6; maxTiles++) {
    const r = greedyWithCap(maxTiles);
    if (r.sum > best.sum) best = r;
    if (r.sum === target) return r;
  }

  // If the compact attempt got within 3% of the target, that's a good,
  // readable answer — otherwise it means 2–6 tiles physically can't reach
  // that far, so fall back to as many tiles as it actually takes.
  const closeEnough = target > 0 && best.sum / target >= 0.97;
  if (closeEnough) return best;

  const unlimited = greedyUnlimited();
  return unlimited.sum > best.sum ? unlimited : best;
}

function MatchScreen({ vault, go, onVisit, onProtected }) {
  const { challenge, protectedSet, partialMap } = vault;
  const [amount, setAmount] = useState("");
  const [result, setResult] = useState(null);
  const [confirmed, setConfirmed] = useState(false);
  const [showSheet, setShowSheet] = useState(false);
  const [wallet, setWallet] = useState(null);
  const [focused, setFocused] = useState(false);
  const [confirmSheet, setConfirmSheet] = useState(false);

  useEffect(() => { onVisit?.(); }, []);
  const available = useMemo(() => {
    const arr = [];
    for (let i = 1; i <= challenge.n; i++) if (!protectedSet.has(i) && !partialMap.has(i)) arr.push(i);
    return arr;
  }, [protectedSet, partialMap, challenge.n]);

  const runMatch = () => {
    const target = Math.round(Number(amount));
    if (!target || target <= 0) return;
    setResult(findMatchCombo(available, target));
    setConfirmed(false);
  };

  const confirm = () => {
    if (!result || !wallet) return;
    result.combo.forEach((n) => onProtected(n));
    setConfirmed(true);
    setShowSheet(false);
  };

  const isExact = result && result.sum === Math.round(Number(amount));

  return (
    <Screen>
      <BackHeader title="Cofre Match™" subtitle="Guarde vários números de uma vez" onBack={() => go("home")} />
      <div className="flex-1 overflow-y-auto no-scrollbar px-5 pb-6 min-h-0">
        <IconHero icon={Shuffle} color={C.blueElectric} />
        <p className="leading-relaxed text-center mt-4" style={fs_(13.5, { color: C.text2 })}>
          Quanto você consegue guardar hoje? O Cofre Match busca a melhor combinação de números disponíveis que soma esse valor.
        </p>
        <div
          className="flex items-center gap-2.5 mt-5 p-3.5 transition-all"
          style={{ background: C.surface1, borderRadius: 16, border: `1.5px solid ${focused ? C.blueElectric : C.strokeSoft}`, boxShadow: focused ? `0 0 0 4px ${C.blueElectric}1a` : "none" }}
        >
          <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(6,164,175,0.12)" }}>
            <span className="font-bold" style={fs_(13, { color: C.blueElectric })}>R$</span>
          </div>
          <input
            type="number" inputMode="numeric" value={amount}
            onChange={(e) => setAmount(e.target.value)}
            onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}
            placeholder="0"
            className="flex-1 bg-transparent outline-none font-bold"
            style={fs_(20, { color: C.text1 })}
          />
        </div>
        <button onClick={runMatch} disabled={!amount} className="w-full py-3.5 rounded-2xl font-semibold mt-3 disabled:opacity-40 active:scale-95 transition-transform cofre-glow-pulse relative overflow-hidden cofre-shine-sweep" style={fs_(14, { ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66`, boxShadow: `0 10px 22px -10px ${C.blueElectric}88` })}>
          Buscar combinação
        </button>

        {result && (
          <div className="mt-6 cofre-pop-in">
            {result.combo.length === 0 ? (
              <p className="text-center mt-4" style={fs_(13, { color: C.text3 })}>Não encontramos números disponíveis para esse valor. Tente um valor diferente.</p>
            ) : (
              <>
                <div className="flex items-center gap-2 mb-3">
                  {isExact ? (
                    <div className="w-6 h-6 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(232,169,61,0.18)" }}>
                      <Sparkles size={13} color={C.gold} />
                    </div>
                  ) : (
                    <div className="w-6 h-6 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(6,164,175,0.14)" }}>
                      <Target size={12} color={C.blueElectric} />
                    </div>
                  )}
                  <p className="font-semibold" style={fs_(13.5, { color: isExact ? C.gold : C.text1 })}>
                    {isExact ? "Combinação exata encontrada!" : "Melhor aproximação encontrada"}
                  </p>
                </div>
                <div className="flex flex-wrap gap-2">
                  {result.combo.slice(0, 24).map((n, i) => (
                    <div key={n} className="px-3.5 py-2 rounded-xl font-semibold cofre-pop-in" style={{ ...fs_(13, { background: "rgba(6,164,175,0.14)", border: `1px solid ${C.blueElectric}66`, color: C.text1 }), animationDelay: `${i * 0.05}s` }}>
                      #{n}
                    </div>
                  ))}
                  {result.combo.length > 24 && (
                    <div className="px-3.5 py-2 rounded-xl font-semibold" style={fs_(13, { background: `${C.gold}22`, border: `1px solid ${C.gold}66`, color: C.text1 })}>
                      +{result.combo.length - 24} números
                    </div>
                  )}
                </div>
                <p className="mt-2" style={fs_(11.5, { color: C.text3 })}>
                  {result.combo.length} {result.combo.length === 1 ? "número" : "números"} nessa combinação
                </p>
                <div className="flex items-center justify-between mt-4 p-3.5" style={{ background: C.surface1, borderRadius: 14, borderLeft: `4px solid ${C.green}`, boxShadow: "0 1px 0 rgba(255,255,255,0.6) inset, 0 14px 28px -18px rgba(20,41,63,0.16)" }}>
                  <span style={fs_(12.5, { color: C.text3 })}>Total protegido</span>
                  <span className="font-bold" style={fs_(17, { color: C.green })}>{fmtBRL(result.sum)}</span>
                </div>
                {confirmed ? (
                  <div className="mt-4 p-4 text-center cofre-pop-in" style={{ background: "rgba(5,130,102,0.1)", border: `1px solid ${C.green}55`, borderRadius: 18 }}>
                    <Check size={22} color={C.green} className="mx-auto mb-1.5" />
                    <p className="font-semibold" style={fs_(13.5, { color: C.text1 })}>{result.combo.length} números protegidos!</p>
                  </div>
                ) : (
                  <button onClick={() => { setWallet(null); setShowSheet(true); }} className="w-full py-4 rounded-2xl font-semibold mt-4 active:scale-95 transition-transform cofre-glow-pulse relative overflow-hidden cofre-shine-sweep" style={fs_(15, { ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66`, boxShadow: `0 10px 26px -10px ${C.blueElectric}88` })}>
                    Confirmar e proteger {fmtBRL(result.sum)}
                  </button>
                )}
              </>
            )}
          </div>
        )}
      </div>
      <BottomNav screen="home" go={go} />

      {showSheet && result && (
        <Sheet onClose={() => setShowSheet(false)}>
          <WalletPicker amount={result.sum} wallet={wallet} setWallet={setWallet} />
          <button disabled={!wallet} onClick={() => setConfirmSheet(true)} className="w-full py-4 rounded-2xl font-semibold mt-6 disabled:opacity-40 active:scale-95 transition-transform cofre-glow-pulse relative overflow-hidden cofre-shine-sweep" style={fs_(15, { ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66` })}>
            PROTEGER {fmtBRL(result.sum)}
          </button>
        </Sheet>
      )}

      {confirmSheet && result && (
        <ConfirmDepositSheet
          amount={result.sum}
          onClose={() => setConfirmSheet(false)}
          onConfirm={() => { setConfirmSheet(false); confirm(); }}
        />
      )}
    </Screen>
  );
}

/* =========================================================================
   SCREEN: ROLETA DO COFRE — a randomizer over available numbers under a
   ceiling the person sets. Not a game of chance over money — it just picks
   which number you'll tackle next.
   ========================================================================= */
function RouletteScreen({ vault, go, onProtected }) {
  const { challenge, protectedSet, partialMap } = vault;
  const [teto, setTeto] = useState("");
  const [spinning, setSpinning] = useState(false);
  const [display, setDisplay] = useState(null);
  const [landed, setLanded] = useState(null);
  const [protectedNow, setProtectedNow] = useState(false);
  const [showSheet, setShowSheet] = useState(false);
  const [wallet, setWallet] = useState(null);
  const [confirmSheet, setConfirmSheet] = useState(false);
  const timerRef = useRef(null);

  const available = useMemo(() => {
    const arr = [];
    for (let i = 1; i <= challenge.n; i++) if (!protectedSet.has(i) && !partialMap.has(i)) arr.push(i);
    return arr;
  }, [protectedSet, partialMap, challenge.n]);

  useEffect(() => () => { if (timerRef.current) clearInterval(timerRef.current); }, []);

  const spin = () => {
    const cap = Math.round(Number(teto));
    const pool = cap > 0 ? available.filter((n) => n <= cap) : available;
    if (pool.length === 0) return;
    setSpinning(true);
    setLanded(null);
    setProtectedNow(false);
    let ticks = 0;
    const maxTicks = 18;
    timerRef.current = setInterval(() => {
      setDisplay(pool[Math.floor(Math.random() * pool.length)]);
      ticks++;
      if (ticks >= maxTicks) {
        clearInterval(timerRef.current);
        const final = pool[Math.floor(Math.random() * pool.length)];
        setDisplay(final);
        setLanded(final);
        setSpinning(false);
      }
    }, 70);
  };

  const confirmProtect = () => {
    if (landed == null || !wallet) return;
    onProtected(landed);
    setProtectedNow(true);
    setShowSheet(false);
  };

  return (
    <Screen>
      <BackHeader title="Roleta do Cofre" subtitle="Desafio aleatório" onBack={() => go("home")} />
      <div className="flex-1 overflow-y-auto no-scrollbar px-5 pb-6 min-h-0 flex flex-col items-center">
        <IconHero icon={CircleDot} color={C.violet} />
        <p className="leading-relaxed text-center mt-4" style={fs_(13.5, { color: C.text2 })}>
          Defina um teto de valor e gire: o Cofre sorteia um número disponível dentro desse limite para você proteger agora.
        </p>

        <div className="flex items-center gap-2.5 mt-5 p-3.5 w-full transition-all" style={{ background: C.surface1, borderRadius: 16, border: `1.5px solid ${C.strokeSoft}` }}>
          <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(73,124,230,0.12)" }}>
            <span className="font-bold" style={fs_(11, { color: C.violet })}>R$</span>
          </div>
          <input
            type="number" inputMode="numeric" value={teto}
            onChange={(e) => setTeto(e.target.value)}
            placeholder={`máx. ${challenge.n}`}
            className="flex-1 bg-transparent outline-none font-bold"
            style={fs_(18, { color: C.text1 })}
          />
        </div>

        <div className="relative flex items-center justify-center mt-8" style={{ width: 200, height: 200 }}>
          {/* pointer */}
          <div className="absolute z-10" style={{ top: -2 }}>
            <div style={{ width: 0, height: 0, borderLeft: "7px solid transparent", borderRight: "7px solid transparent", borderTop: `12px solid ${C.violet}` }} />
          </div>
          {/* tick ring */}
          <svg width={200} height={200} className={spinning ? "cofre-ring-spin" : undefined} style={{ position: "absolute" }}>
            {Array.from({ length: 24 }, (_, i) => {
              const angle = (i / 24) * 2 * Math.PI;
              const r1 = 92, r2 = 100;
              const x1 = 100 + r1 * Math.cos(angle), y1 = 100 + r1 * Math.sin(angle);
              const x2 = 100 + r2 * Math.cos(angle), y2 = 100 + r2 * Math.sin(angle);
              return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={spinning ? C.violet : C.strokeSoft} strokeWidth={2} strokeLinecap="round" opacity={spinning ? 0.8 : 0.5} />;
            })}
          </svg>
          {/* sparkles while spinning */}
          {spinning && [0, 1, 2, 3].map((i) => (
            <div key={i} className="absolute cofre-sparkle" style={{ top: `${15 + i * 18}%`, left: i % 2 === 0 ? "8%" : "84%", animationDelay: `${i * 0.2}s` }}>
              <Sparkles size={12} color={C.gold} />
            </div>
          ))}
          <div
            className="rounded-full flex items-center justify-center relative"
            style={{
              width: 154, height: 154,
              background: "radial-gradient(circle, rgba(73,124,230,0.16) 0%, #fff 72%)",
              border: `2px solid ${spinning ? C.violet : C.strokeSoft}`,
              boxShadow: spinning ? `0 0 40px -4px ${C.violet}aa` : "0 8px 20px -10px rgba(20,41,63,0.2)",
              transition: "box-shadow 0.3s ease",
            }}
          >
            <span key={display} className="font-bold tabular-nums cofre-number-flip" style={fs_(40, { color: C.text1 })}>{display ?? "?"}</span>
          </div>
        </div>

        {landed != null && !spinning && (
          <p className="mt-3 font-medium cofre-pop-in" style={fs_(13, { color: C.text2 })}>Número {landed} · {fmtBRL(landed)}</p>
        )}

        <button onClick={spin} disabled={spinning} className="w-full py-4 rounded-2xl font-semibold mt-8 disabled:opacity-50 active:scale-95 transition-transform" style={fs_(15, { backgroundImage: `linear-gradient(90deg, ${C.violet} 0%, ${C.blueElectric} 100%)`, color: "#fff", boxShadow: `0 10px 26px -10px ${C.violet}88` })}>
          {spinning ? "Girando..." : "Girar roleta"}
        </button>

        {landed != null && !spinning && (
          protectedNow ? (
            <div className="mt-4 p-4 text-center w-full cofre-pop-in" style={{ background: "rgba(5,130,102,0.1)", border: `1px solid ${C.green}55`, borderRadius: 18 }}>
              <Check size={22} color={C.green} className="mx-auto mb-1.5" />
              <p className="font-semibold" style={fs_(13.5, { color: C.text1 })}>Número {landed} protegido!</p>
            </div>
          ) : (
            <button onClick={() => { setWallet(null); setShowSheet(true); }} className="w-full py-4 rounded-2xl font-semibold mt-3 active:scale-95 transition-transform" style={fs_(15, { background: "rgba(20,41,63,0.07)", color: C.text1, border: `1px solid ${C.strokeSoft}` })}>
              Aceitar e proteger {fmtBRL(landed)}
            </button>
          )
        )}
      </div>
      <BottomNav screen="home" go={go} />

      {showSheet && landed != null && (
        <Sheet onClose={() => setShowSheet(false)}>
          <WalletPicker amount={landed} wallet={wallet} setWallet={setWallet} />
          <button disabled={!wallet} onClick={() => setConfirmSheet(true)} className="w-full py-4 rounded-2xl font-semibold mt-6 disabled:opacity-40 active:scale-95 transition-transform cofre-glow-pulse relative overflow-hidden cofre-shine-sweep" style={fs_(15, { ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66` })}>
            PROTEGER {fmtBRL(landed)}
          </button>
        </Sheet>
      )}

      {confirmSheet && landed != null && (
        <ConfirmDepositSheet
          amount={landed}
          onClose={() => setConfirmSheet(false)}
          onConfirm={() => { setConfirmSheet(false); confirmProtect(); }}
        />
      )}
    </Screen>
  );
}

/* =========================================================================
   SCREEN: CAÇA AO NÚMERO — pick a specific target number and see what it
   takes to protect exactly that one.
   ========================================================================= */
const HUNT_TIP_CATEGORIES = [
  {
    title: "Venda o que você não usa",
    icon: ShoppingBag,
    color: C.blueElectric,
    tips: [
      "Roupas e calçados parados no armário: separe e venda em brechós ou grupos de desapego no WhatsApp/Facebook",
      "Eletrônicos antigos (celular, fone, carregador, cabo): sites de recompra pagam à vista",
      "Móveis e objetos de casa parados há meses: anuncie no OLX ou Facebook Marketplace",
      "Livros, jogos, discos e coleções que você já não olha mais",
    ],
  },
  {
    title: "Corte um gasto pequeno",
    icon: Scissors,
    color: C.amber,
    tips: [
      "Pule o delivery desta semana e guarde a diferença do que gastaria",
      "Cancele uma assinatura que você esqueceu que tinha (streaming, app, academia parada)",
      "Leve marmita ao invés de comprar almoço por 2–3 dias",
      "Troque uma saída cara por uma opção gratuita ou mais barata neste fim de semana",
    ],
  },
  {
    title: "Gere uma renda extra rápida",
    icon: Briefcase,
    color: C.violet,
    tips: [
      "Ofereça um freela de um dia na sua área (design, aula, conserto, serviço manual)",
      "Divulgue uma habilidade sua em grupos de bairro ou comunidade",
      "Faça uma entrega, um frete ou cuide de um pet por um app",
      "Venda um serviço que você já sabe fazer para um vizinho ou conhecido",
    ],
  },
  {
    title: "Garimpe dinheiro esquecido",
    icon: SearchIcon,
    color: C.green,
    tips: [
      "Saldo parado em apps de cashback, carteiras digitais ou pontos que viram dinheiro",
      "Troco de compras antigas ou reembolsos que ainda não caíram",
      "Valores a receber: emprestou pra alguém? Pode ser a hora de cobrar com carinho",
      "Confira se sobrou limite em algum vale ou benefício que você não vem usando",
    ],
  },
];

function HuntScreen({ vault, go, openNumber }) {
  const { challenge, protectedSet, partialMap } = vault;
  const [target, setTarget] = useState("");
  const [focused, setFocused] = useState(false);
  const n = Math.round(Number(target));
  const valid = n > 0 && n <= challenge.n;
  const already = valid && protectedSet.has(n);
  const partial = valid && partialMap.has(n);

  return (
    <Screen>
      <BackHeader title="Caça ao Número" subtitle="Missões para ganhar" onBack={() => go("home")} />
      <div className="flex-1 overflow-y-auto no-scrollbar px-5 pb-6 min-h-0">
        <IconHero icon={Target} color={C.green} />
        <p className="leading-relaxed text-center mt-4" style={fs_(13.5, { color: C.text2 })}>
          Escolha um número específico do seu tabuleiro e vamos te ajudar a conquistar exatamente esse valor.
        </p>
        <div
          className="flex items-center gap-2.5 mt-5 p-3.5 transition-all"
          style={{ background: C.surface1, borderRadius: 16, border: `1.5px solid ${focused ? C.green : C.strokeSoft}`, boxShadow: focused ? `0 0 0 4px ${C.green}1a` : "none" }}
        >
          <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(5,130,102,0.12)" }}>
            <Target size={14} color={C.green} />
          </div>
          <input
            type="number" inputMode="numeric" value={target}
            onChange={(e) => setTarget(e.target.value)}
            onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}
            placeholder={`Número (1–${fmtInt(challenge.n)})`}
            className="flex-1 bg-transparent outline-none font-bold"
            style={fs_(17, { color: C.text1 })}
          />
        </div>

        {target && !valid && (
          <p className="mt-3" style={fs_(12.5, { color: C.danger })}>Escolha um número entre 1 e {fmtInt(challenge.n)}.</p>
        )}

        {valid && (
          <div className="mt-5 cofre-pop-in">
            <div className="p-4 flex items-center gap-4" style={{ background: "linear-gradient(135deg, rgba(5,130,102,0.08), rgba(6,164,175,0.05))", border: `1.5px solid ${C.green}33`, borderRadius: 18 }}>
              <div className="w-14 h-14 rounded-full flex items-center justify-center shrink-0" style={{ background: C.surface1, boxShadow: `0 6px 16px -6px ${C.green}55` }}>
                <span className="font-bold" style={fs_(18, { color: C.green })}>#{n}</span>
              </div>
              <div>
                <p style={fs_(12, { color: C.text3 })}>Número escolhido</p>
                <p className="font-bold mt-0.5" style={fs_(20, { color: C.text1 })}>{fmtBRL(n)}</p>
              </div>
            </div>

            {already ? (
              <div className="mt-4 p-4 text-center cofre-pop-in" style={{ background: "rgba(5,130,102,0.1)", border: `1px solid ${C.green}55`, borderRadius: 18 }}>
                <Check size={20} color={C.green} className="mx-auto mb-1" />
                <p className="font-semibold" style={fs_(13, { color: C.text1 })}>Esse número já está protegido!</p>
              </div>
            ) : (
              <>
                <p className="font-semibold mt-5 mb-2" style={fs_(13, { color: C.text1 })}>Ideias para conquistar {fmtBRL(n)}</p>
                <div className="flex flex-col gap-3">
                  {HUNT_TIP_CATEGORIES.map((cat, ci) => {
                    const CatIcon = cat.icon;
                    return (
                      <div key={cat.title} className="p-3.5 cofre-pop-in" style={{ background: C.surface1, borderRadius: 14, borderLeft: `4px solid ${cat.color}`, boxShadow: "0 1px 0 rgba(255,255,255,0.6) inset, 0 14px 28px -18px rgba(20,41,63,0.16)", animationDelay: `${ci * 0.06}s` }}>
                        <div className="flex items-center gap-2 mb-2">
                          <div className="w-7 h-7 rounded-full flex items-center justify-center shrink-0" style={{ background: `${cat.color}1f` }}>
                            <CatIcon size={13} color={cat.color} />
                          </div>
                          <span className="font-semibold" style={fs_(12.5, { color: C.text1 })}>{cat.title}</span>
                        </div>
                        <div className="flex flex-col gap-1.5">
                          {cat.tips.map((t) => (
                            <div key={t} className="flex items-start gap-2">
                              <span className="mt-1.5 rounded-full shrink-0" style={{ width: 3, height: 3, background: cat.color }} />
                              <span className="leading-relaxed" style={fs_(12, { color: C.text2 })}>{t}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    );
                  })}
                </div>
                <button onClick={() => openNumber(n, partial ? "partial" : "available")} className="w-full py-4 rounded-2xl font-semibold mt-5 active:scale-95 transition-transform cofre-glow-pulse relative overflow-hidden cofre-shine-sweep" style={fs_(15, { ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66` })}>
                  Já consegui, proteger agora
                </button>
              </>
            )}
          </div>
        )}
      </div>
      <BottomNav screen="home" go={go} />
    </Screen>
  );
}

/* =========================================================================
   SCREEN: STUB / WALLETS / MISSIONS / PROFILE
   ========================================================================= */
function StubScreen({ label, go }) {
  return (
    <Screen>
      <BackHeader title={label || "Em breve"} onBack={() => go("home")} />
      <div className="flex-1 flex flex-col items-center justify-center px-8 text-center min-h-0">
        <Sparkles size={30} color={C.blueElectric} />
        <p className="mt-4" style={fs_(14.5, { color: C.text2 })}>Essa experiência está sendo lapidada com o mesmo capricho do resto do Cofre.</p>
      </div>
      <BottomNav screen="home" go={go} />
    </Screen>
  );
}

const WALLET_ROWS_META = [
  { id: "cdb", l: "CDB", c: C.blueElectric, icon: Landmark },
  { id: "tesouro", l: "Tesouro Selic", c: C.cyan, icon: Building2 },
  { id: "poupanca", l: "Poupança", c: C.text3, icon: PiggyBank },
  { id: "reserva", l: "Conta de reserva", c: C.violet, icon: Wallet },
  { id: "casa", l: "Dinheiro em casa", c: C.gold, icon: Banknote },
];

function WalletsScreen({ go }) {
  // Zero balances by default — a fresh Cofre means nothing has been
  // distributed to an outside wallet yet either.
  const [balances, setBalances] = useState({ cdb: 0, tesouro: 0, poupanca: 0, reserva: 0, casa: 0 });
  const [moveFrom, setMoveFrom] = useState(null); // wallet id being moved out of
  const [moveTo, setMoveTo] = useState(null);
  const [amount, setAmount] = useState("");

  const total = Object.values(balances).reduce((a, v) => a + v, 0);
  const maxTotal = Math.max(1, total);
  const hasAny = total > 0;

  const openMove = (id) => { setMoveFrom(id); setMoveTo(null); setAmount(""); };
  const closeMove = () => setMoveFrom(null);

  const confirmMove = () => {
    const n = Math.round(Number(amount));
    if (!moveFrom || !moveTo || moveFrom === moveTo || !n || n <= 0 || n > balances[moveFrom]) return;
    setBalances((prev) => ({ ...prev, [moveFrom]: prev[moveFrom] - n, [moveTo]: prev[moveTo] + n }));
    closeMove();
  };

  const fromMeta = WALLET_ROWS_META.find((w) => w.id === moveFrom);
  const pieData = WALLET_ROWS_META.filter((r) => balances[r.id] > 0).map((r) => ({ name: r.l, value: balances[r.id], color: r.c }));

  return (
    <Screen>
      <BackHeader title="Meu Dinheiro" subtitle="Onde está guardado, fora do Cofre" onBack={() => go("home")} />
      <div className="flex-1 overflow-y-auto no-scrollbar px-5 pb-6 min-h-0">
        <div className="p-5" style={{ background: C.surface1, borderRadius: 20, boxShadow: "0 1px 0 rgba(255,255,255,0.6) inset, 0 14px 28px -18px rgba(20,41,63,0.16)" }}>
          <div className="flex items-center gap-4">
            <div className="relative shrink-0" style={{ width: 84, height: 84 }}>
              {hasAny ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={pieData} dataKey="value" nameKey="name" innerRadius={26} outerRadius={40} paddingAngle={3} strokeWidth={0}>
                      {pieData.map((d, i) => <Cell key={i} fill={d.color} />)}
                    </Pie>
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="rounded-full flex items-center justify-center" style={{ width: "100%", height: "100%", border: `3px dashed ${C.strokeSoft}` }}>
                  <Wallet size={22} color={C.text3} />
                </div>
              )}
            </div>
            <div>
              <p style={fs_(12, { color: C.text3 })}>Total distribuído</p>
              <p className="font-bold mt-0.5" style={fs_(24, { color: C.text1 })}>{fmtBRL(total)}</p>
              {!hasAny && <p className="mt-1" style={fs_(11, { color: C.text3 })}>Nada guardado fora do Cofre ainda</p>}
            </div>
          </div>
        </div>

        {!hasAny && (
          <div className="p-4 mt-3 flex items-start gap-3" style={{ background: "rgba(6,164,175,0.06)", border: `1px solid ${C.blueElectric}33`, borderRadius: 18 }}>
            <Info size={16} color={C.blueElectric} className="mt-0.5 shrink-0" />
            <p className="leading-relaxed" style={fs_(12, { color: C.text2 })}>
              Assim que você proteger um número e escolher onde guardou, esse valor aparece aqui automaticamente.
            </p>
          </div>
        )}

        <p className="mt-4" style={fs_(11.5, { color: C.text3 })}>Toque em qualquer carteira para mover dinheiro dela para outra.</p>
        <div className="flex flex-col gap-2.5 mt-2">
          {WALLET_ROWS_META.map((r) => {
            const Icon = r.icon;
            const v = balances[r.id];
            return (
              <button key={r.id} onClick={() => openMove(r.id)} className="p-3.5 flex items-center gap-3 text-left active:scale-95 transition-transform" style={{ ...glass, borderRadius: 14 }}>
                <div className="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ background: `${r.c}1f` }}>
                  <Icon size={16} color={r.c} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium" style={fs_(13, { color: C.text1 })}>{r.l}</p>
                  <div className="h-1 rounded-full mt-1.5" style={{ background: "rgba(20,41,63,0.07)", width: "100%" }}>
                    <div className="h-full rounded-full transition-all duration-500" style={{ width: `${(v / maxTotal) * 100}%`, background: r.c }} />
                  </div>
                </div>
                <p className="font-semibold shrink-0" style={fs_(13, { color: C.text1 })}>{fmtBRL(v)}</p>
                <ChevronRight size={15} color={C.text3} className="shrink-0" />
              </button>
            );
          })}
        </div>
      </div>
      <BottomNav screen="wealth" go={go} />

      {moveFrom && (
        <Sheet onClose={closeMove}>
          <h3 className="font-bold text-center" style={fs_(17, { color: C.text1 })}>Mover de {fromMeta?.l}</h3>
          <p className="text-center mt-1" style={fs_(12, { color: C.text3 })}>Disponível: {fmtBRL(balances[moveFrom])}</p>

          <div className="flex items-center gap-2 mt-4 p-3.5" style={{ ...glass, borderRadius: 14 }}>
            <span style={fs_(15, { color: C.text3 })}>R$</span>
            <input
              type="number" inputMode="numeric" value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="0"
              className="flex-1 bg-transparent outline-none font-semibold"
              style={fs_(18, { color: C.text1 })}
            />
            <button onClick={() => setAmount(String(balances[moveFrom]))} className="px-2.5 py-1 rounded-full font-medium" style={fs_(11, { color: C.blueElectric, background: "rgba(6,164,175,0.1)" })}>
              Tudo
            </button>
          </div>

          <p className="font-semibold mt-5 mb-2" style={fs_(13, { color: C.text1 })}>Para onde?</p>
          <div className="flex flex-col gap-2">
            {WALLET_ROWS_META.filter((w) => w.id !== moveFrom).map((w) => {
              const Icon = w.icon;
              const active = moveTo === w.id;
              return (
                <button key={w.id} onClick={() => setMoveTo(w.id)} className="p-3 flex items-center gap-3 text-left active:scale-95 transition-transform" style={{ ...(active ? glassActive : glass), borderRadius: 14 }}>
                  <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: `${w.c}1f` }}>
                    <Icon size={15} color={w.c} />
                  </div>
                  <span className="font-medium flex-1" style={fs_(13, { color: C.text1 })}>{w.l}</span>
                  <span style={fs_(11.5, { color: C.text3 })}>{fmtBRL(balances[w.id])}</span>
                </button>
              );
            })}
          </div>

          <button
            disabled={!moveTo || !amount || Number(amount) <= 0 || Number(amount) > balances[moveFrom]}
            onClick={confirmMove}
            className="w-full py-4 rounded-2xl font-semibold mt-6 disabled:opacity-40 active:scale-95 transition-transform cofre-glow-pulse relative overflow-hidden cofre-shine-sweep"
            style={fs_(15, { ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66` })}
          >
            Confirmar movimentação
          </button>
        </Sheet>
      )}
    </Screen>
  );
}

function MissionsScreen({ go, streak, protectedToday, visitedMatch }) {
  const missions = [
    {
      l: "Proteja 1 número hoje",
      pct: Math.min(100, protectedToday * 100),
      xp: 20,
      done: protectedToday >= 1,
      icon: Lock,
    },
    {
      l: "Visite o Cofre Match™",
      pct: visitedMatch ? 100 : 0,
      xp: 15,
      done: visitedMatch,
      icon: Shuffle,
    },
    {
      l: "Mantenha a sequência viva",
      pct: Math.min(100, Math.round((streak / 7) * 100)),
      xp: 25,
      done: streak >= 7,
      icon: Flame,
    },
    {
      l: "Proteja 3 números hoje",
      pct: Math.min(100, Math.round((protectedToday / 3) * 100)),
      xp: 60,
      done: protectedToday >= 3,
      icon: Target,
    },
  ];
  const doneCount = missions.filter((m) => m.done).length;
  const earnedPts = missions.filter((m) => m.done).reduce((s, m) => s + m.xp, 0);
  const totalPts = missions.reduce((s, m) => s + m.xp, 0);

  return (
    <Screen>
      <BackHeader title="Missões" subtitle="Hoje" onBack={() => go("home")} />
      <div className="flex-1 overflow-y-auto no-scrollbar px-5 pb-6 min-h-0">
        <div className="p-4 flex items-center gap-4" style={{ ...glassActive, borderRadius: 18 }}>
          <div className="relative w-16 h-16 shrink-0">
            <svg viewBox="0 0 64 64" className="w-16 h-16 -rotate-90">
              <circle cx="32" cy="32" r="27" fill="none" stroke={C.strokeSoft} strokeWidth="6" />
              <circle
                cx="32" cy="32" r="27" fill="none" stroke={C.gold} strokeWidth="6" strokeLinecap="round"
                strokeDasharray={2 * Math.PI * 27}
                strokeDashoffset={2 * Math.PI * 27 * (1 - doneCount / missions.length)}
                style={{ transition: "stroke-dashoffset 0.5s ease" }}
              />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center font-bold" style={fs_(15, { color: C.text1 })}>
              {doneCount}/{missions.length}
            </div>
          </div>
          <div className="min-w-0">
            <p className="font-semibold" style={fs_(14, { color: C.text1 })}>
              {doneCount === missions.length ? "Todas concluídas hoje! 🎉" : "Missões de hoje"}
            </p>
            <p className="mt-0.5" style={fs_(12, { color: C.text3 })}>
              <span style={{ color: C.gold, fontWeight: 600 }}>+{earnedPts} pts</span> de {totalPts} disponíveis
            </p>
            <p className="mt-1.5" style={fs_(10.5, { color: C.text3 })}>Renovam à meia-noite</p>
          </div>
        </div>

        <div className="flex flex-col gap-2.5 mt-4">
          {missions.map((m) => {
            const Icon = m.icon;
            return (
              <div key={m.l} className="p-4" style={{ ...glass, borderRadius: 14 }}>
                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2.5 min-w-0">
                    <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0" style={{ background: m.done ? "rgba(5,130,102,0.16)" : "rgba(20,41,63,0.055)" }}>
                      {m.done ? <Check size={15} color={C.green} /> : <Icon size={14} color={C.text3} />}
                    </div>
                    <p className="font-medium truncate" style={fs_(13, { color: C.text1 })}>{m.l}</p>
                  </div>
                  <span className="font-semibold shrink-0" style={fs_(11.5, { color: m.done ? C.green : C.gold })}>+{m.xp} pts</span>
                </div>
                <div className="h-1.5 rounded-full mt-3" style={{ background: "rgba(20,41,63,0.07)" }}>
                  <div className="h-full rounded-full" style={{ width: `${m.pct}%`, ...(m.done ? progressGradient : ctaGradient) }} />
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-5 p-4 flex items-start gap-2.5" style={{ background: `${C.blueElectric}0f`, border: `1px solid ${C.blueElectric}33`, borderRadius: 14 }}>
          <Info size={15} color={C.blueElectric} className="mt-0.5 shrink-0" />
          <p className="leading-relaxed" style={fs_(11.5, { color: C.text2 })}>
            As missões acompanham o que você faz nesta sessão. Proteger números e visitar o Cofre Match são reais, atualizados na hora.
          </p>
        </div>
      </div>
      <BottomNav screen="missions" go={go} />
    </Screen>
  );
}

function ProfileScreen({ go, level, vault, streak, onResetProgress, themeName, onSetTheme, avatarUrl, onSetAvatar }) {
  const [confirmReset, setConfirmReset] = useState(false);
  const [themeSheet, setThemeSheet] = useState(false);
  const fileInputRef = useRef(null);
  const ctx = {
    protectedCount: vault?.protectedSet?.size ?? 0,
    protectedTotal: vault?.protectedTotal ?? 0,
    progressPct: vault?.progressPct ?? 0,
    streak: streak ?? 0,
  };
  const unlockedCount = evaluateAchievements(ctx).filter((b) => b.unlocked).length;
  const rank = guardianRank(ctx.protectedCount);

  const handlePhotoPick = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => onSetAvatar(reader.result);
    reader.readAsDataURL(file);
    e.target.value = "";
  };

  return (
    <Screen>
      <BackHeader title="Você" onBack={() => go("home")} />
      <div className="flex-1 overflow-y-auto no-scrollbar px-5 pb-6 min-h-0">
        <div className="flex flex-col items-center pt-2 pb-2">
          <input ref={fileInputRef} type="file" accept="image/*" onChange={handlePhotoPick} style={{ display: "none" }} />
          <button onClick={() => fileInputRef.current?.click()} className="relative w-20 h-20 active:scale-95 transition-transform">
            {avatarUrl ? (
              <img src={avatarUrl} alt="Sua foto" className="w-20 h-20 rounded-full object-cover" style={{ border: `2px solid ${C.strokeActive}` }} />
            ) : (
              <div className="w-20 h-20 rounded-full" style={{ background: `linear-gradient(135deg, ${C.violet}, ${C.blueElectric})`, border: `2px solid ${C.strokeActive}` }} />
            )}
            <span className="absolute -bottom-1 -right-1 w-7 h-7 rounded-full flex items-center justify-center" style={{ background: C.blueElectric, border: `2px solid ${C.surface1}` }}>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2Z" />
                <circle cx="12" cy="13" r="4" />
              </svg>
            </span>
          </button>
          <p className="font-semibold mt-3" style={fs_(16, { color: C.text1 })}>{rank.name} · Nível {rank.level}</p>
          <p style={fs_(12, { color: C.text3 })}>Membro desde jan 2026</p>
        </div>
        <div className="grid grid-cols-2 gap-3 mt-4">
          <button onClick={() => go("achievements")} className="p-4 text-left active:scale-95 transition-transform" style={{ ...glass, borderRadius: 18 }}>
            <Trophy size={18} color={C.gold} />
            <p className="font-semibold mt-2" style={fs_(13, { color: C.text1 })}>Conquistas</p>
            <p style={fs_(11, { color: C.text3 })}>{unlockedCount} badges</p>
          </button>
          <button onClick={() => go("journey")} className="p-4 text-left active:scale-95 transition-transform" style={{ ...glass, borderRadius: 18 }}>
            <Sparkles size={18} color={C.violet} />
            <p className="font-semibold mt-2" style={fs_(13, { color: C.text1 })}>Jornada</p>
            <p style={fs_(11, { color: C.text3 })}>Mimos e marcos</p>
          </button>
          <button onClick={() => go("mystery")} className="p-4 text-left active:scale-95 transition-transform" style={{ ...glass, borderRadius: 18 }}>
            <Gift size={18} color={C.gold} />
            <p className="font-semibold mt-2" style={fs_(13, { color: C.text1 })}>Caixa Misteriosa</p>
            <p style={fs_(11, { color: C.text3 })}>Presente final</p>
          </button>
          <button onClick={() => go("withdraw")} className="p-4 text-left active:scale-95 transition-transform" style={{ ...glass, borderRadius: 18 }}>
            <LockOpen size={18} color={C.danger} />
            <p className="font-semibold mt-2" style={fs_(13, { color: C.text1 })}>Abrir Cofre</p>
            <p style={fs_(11, { color: C.text3 })}>Retirada com cuidado</p>
          </button>
        </div>
        <p className="font-semibold mt-6 mb-3" style={fs_(13, { color: C.text1 })}>Configurações</p>
        <div className="flex flex-col gap-2">
          {["Notificações", "Modo discreto", "Intensidade de animação"].map((s) => (
            <div key={s} className="p-3.5 flex items-center justify-between" style={{ ...glass, borderRadius: 14 }}>
              <span style={fs_(13, { color: C.text1 })}>{s}</span>
              <ChevronRight size={15} color={C.text3} />
            </div>
          ))}
          <button onClick={() => setThemeSheet(true)} className="p-3.5 flex items-center justify-between text-left active:scale-95 transition-transform" style={{ ...glass, borderRadius: 14 }}>
            <span style={fs_(13, { color: C.text1 })}>Tema</span>
            <span className="flex items-center gap-1.5">
              <span style={fs_(12.5, { color: C.text3 })}>{{ clean: "Clean", soft: "Soft", black: "Black" }[themeName]}</span>
              <ChevronRight size={15} color={C.text3} />
            </span>
          </button>
          {["Exportar dados", "Ajuda"].map((s) => (
            <div key={s} className="p-3.5 flex items-center justify-between" style={{ ...glass, borderRadius: 14 }}>
              <span style={fs_(13, { color: C.text1 })}>{s}</span>
              <ChevronRight size={15} color={C.text3} />
            </div>
          ))}
          <button onClick={() => setConfirmReset(true)} className="p-3.5 flex items-center justify-between text-left active:scale-95 transition-transform" style={{ background: "rgba(225,84,75,0.06)", border: `1px solid ${C.danger}33`, borderRadius: 14 }}>
            <span style={fs_(13, { color: C.danger })}>Resetar progresso</span>
            <ChevronRight size={15} color={C.danger} />
          </button>
          <button onClick={() => supabase.auth.signOut()} className="p-3.5 flex items-center justify-between text-left active:scale-95 transition-transform" style={{ ...glass, borderRadius: 14 }}>
            <span className="flex items-center gap-2" style={fs_(13, { color: C.text1 })}><LogOut size={15} color={C.text3} /> Sair da conta</span>
            <ChevronRight size={15} color={C.text3} />
          </button>
        </div>
      </div>
      <BottomNav screen="profile" go={go} />

      {themeSheet && (
        <Sheet onClose={() => setThemeSheet(false)}>
          <h3 className="font-bold text-center mb-4" style={fs_(17, { color: C.text1 })}>Escolha o tema</h3>
          <div className="flex flex-col gap-2.5 mb-2">
            {[
              { id: "clean", label: "Clean", sub: "Claro, cofre azul", Icon: Sun, iconColor: C.blueElectric },
              { id: "soft", label: "Soft", sub: "Cinza claro, cofre preto e dourado", Icon: Cloud, iconColor: C.gold },
              { id: "black", label: "Black", sub: "Escuro premium, cofre preto e dourado", Icon: Moon, iconColor: C.gold },
            ].map((opt) => (
              <button
                key={opt.id}
                onClick={() => { onSetTheme(opt.id); setThemeSheet(false); }}
                className="w-full p-3.5 flex items-center gap-3 text-left active:scale-95 transition-transform"
                style={themeName === opt.id ? { ...glassActive, borderRadius: 16 } : { ...glass, borderRadius: 16 }}
              >
                <div className="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ background: `${opt.iconColor}1f` }}>
                  <opt.Icon size={17} color={opt.iconColor} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-semibold" style={fs_(14, { color: C.text1 })}>{opt.label}</p>
                  <p style={fs_(11.5, { color: C.text3 })}>{opt.sub}</p>
                </div>
                {themeName === opt.id && <Check size={18} color={C.blueElectric} />}
              </button>
            ))}
          </div>
        </Sheet>
      )}

      {confirmReset && (
        <Sheet onClose={() => setConfirmReset(false)}>
          <div className="flex flex-col items-center text-center">
            <div className="w-14 h-14 rounded-full flex items-center justify-center mb-3" style={{ background: "rgba(225,84,75,0.1)" }}>
              <LockOpen size={24} color={C.danger} />
            </div>
            <h3 className="font-bold" style={fs_(18, { color: C.text1 })}>Resetar todo o progresso?</h3>
            <p className="mt-2 leading-relaxed" style={fs_(13, { color: C.text2 })}>
              Isso zera números protegidos, sequência, nível e mimos, como se você estivesse começando do zero. Não pode ser desfeito.
            </p>
          </div>
          <button
            onClick={() => { setConfirmReset(false); onResetProgress?.(); }}
            className="w-full py-4 rounded-2xl font-semibold mt-6 active:scale-95 transition-transform"
            style={fs_(15, { background: C.danger, color: "#fff" })}
          >
            Sim, resetar tudo
          </button>
          <button onClick={() => setConfirmReset(false)} className="w-full py-3.5 rounded-2xl font-semibold mt-2.5 active:scale-95 transition-transform" style={fs_(14, { background: "rgba(20,41,63,0.05)", color: C.text1 })}>
            Cancelar
          </button>
        </Sheet>
      )}
    </Screen>

  );
}

/* =========================================================================
   COIN RAIN — celebratory burst of gold coins whenever a number gets
   protected. Purely decorative: pointer-events none, self-contained CSS
   animation, no state loop (each burst is a fresh mount via a `key` bump
   in the parent, so it always restarts clean).
   ========================================================================= */
function CoinRain() {
  const coins = useMemo(() => {
    const count = 26;
    return Array.from({ length: count }, (_, i) => ({
      id: i,
      left: Math.random() * 96 + 2,
      size: 7 + Math.random() * 6,
      delay: Math.random() * 0.35,
      duration: 1.5 + Math.random() * 1,
      rot: (Math.random() > 0.5 ? 1 : -1) * (360 + Math.random() * 360),
      drift: (Math.random() - 0.5) * 60,
    }));
  }, []);

  return (
    <div className="absolute inset-0 z-50 overflow-hidden" style={{ pointerEvents: "none" }}>
      {coins.map((c) => (
        <span
          key={c.id}
          className="cofre-coin rounded-full"
          style={{
            left: `${c.left}%`,
            width: c.size,
            height: c.size,
            animationDelay: `${c.delay}s`,
            animationDuration: `${c.duration}s`,
            "--coin-rot": `${c.rot}deg`,
            transform: `translateX(${c.drift}px)`,
            background: "radial-gradient(circle at 35% 30%, #FFF3C4 0%, #F6D877 22%, #E8A93D 55%, #A3661B 100%)",
            boxShadow: `0 0 0 ${Math.max(1, c.size * 0.08)}px #FBD780 inset, 0 2px 4px rgba(0,0,0,0.3)`,
          }}
        />
      ))}
    </div>
  );
}

/* =========================================================================
   LIGHT BURST — a scatter of tiny golden light dots that twinkle across
   the whole screen, used as a "let's go" celebration moment (currently:
   finishing the onboarding tour). Lighter and quieter than CoinRain, no
   falling motion, just points of light appearing and fading in place.
   ========================================================================= */
function LightBurst() {
  const dots = useMemo(() => {
    return Array.from({ length: 34 }, (_, i) => ({
      id: i,
      left: Math.random() * 100,
      top: Math.random() * 100,
      size: 3 + Math.random() * 5,
      delay: Math.random() * 0.7,
      duration: 0.9 + Math.random() * 0.9,
    }));
  }, []);

  return (
    <div className="absolute inset-0 z-50 overflow-hidden" style={{ pointerEvents: "none" }}>
      {dots.map((d) => (
        <span
          key={d.id}
          className="cofre-sparkle-dot"
          style={{
            left: `${d.left}%`,
            top: `${d.top}%`,
            width: d.size,
            height: d.size,
            background: "radial-gradient(circle, #FFF6D8 0%, #E8A93D 65%, transparent 100%)",
            boxShadow: `0 0 ${d.size * 2.2}px ${d.size / 2}px rgba(232,169,61,0.55)`,
            animationDelay: `${d.delay}s`,
            animationDuration: `${d.duration}s`,
          }}
        />
      ))}
    </div>
  );
}

/* =========================================================================
   ONBOARDING TOUR — explains the core mechanic: mark one number per day,
   and shows the actual math for the vault the person just picked (years
   to finish at 1/day, vs. how much marking more per day speeds it up).
   Purely informational, dismissible, and can be reopened any time.
   ========================================================================= */
function OnboardingTour({ vault, onClose, onFinish }) {
  const [step, setStep] = useState(0);
  const [perDay, setPerDay] = useState(3);
  const n = vault?.challenge?.n ?? 500;
  const total = vault?.challenge?.total ?? (n * (n + 1)) / 2;
  const avgPerNumber = total / n;

  const daysAt1 = n;
  const yearsAt1 = daysAt1 / 365;
  const daysAtN = Math.ceil(n / perDay);
  const yearsAtN = daysAtN / 365;

  const fmtYears = (y) => {
    if (y >= 1) return `${y.toFixed(1)} anos`;
    const months = y * 12;
    if (months >= 1) return `${Math.round(months)} meses`;
    return `${Math.max(1, Math.round(y * 365))} dias`;
  };

  const valueByDays = (days) => Math.min(total, Math.round(avgPerNumber * days));

  const steps = [
    {
      icon: Target,
      color: C.blueElectric,
      title: "Como o Cofre funciona",
      body: (
        <>
          <div className="flex flex-col gap-4">
            {[
              { text: <>Todo dia, marque <b style={{ color: C.text1 }}>pelo menos 1 número</b> do seu tabuleiro.</> },
              { text: <>Cada número marcado protege aquele valor dentro do cofre.</> },
              { text: <>Aos poucos, seguindo esse ritmo, seu patrimônio se forma sozinho.</> },
            ].map((item, i) => (
              <div key={i} className="flex items-start gap-3">
                <div className="w-7 h-7 rounded-full flex items-center justify-center shrink-0 font-bold" style={fs_(13, { background: `${C.blueElectric}1f`, color: C.blueElectric })}>
                  {i + 1}
                </div>
                <p style={fs_(14.5, { color: C.text2, lineHeight: 1.65 })}>{item.text}</p>
              </div>
            ))}
          </div>
          <p className="mt-5 font-semibold text-center" style={fs_(14, { color: C.text1, lineHeight: 1.6 })}>
            É simples assim. A disciplina de marcar todo dia é o motor de tudo.
          </p>
        </>
      ),
    },
    {
      icon: Shield,
      color: C.danger,
      title: "A regra de ouro",
      body: (
        <>
          <p style={fs_(14.5, { color: C.text2, lineHeight: 1.75 })}>
            Antes de marcar qualquer número, faça sempre esta pergunta:
          </p>
          <div className="mt-5 flex flex-col gap-2.5">
            <div className="flex items-center gap-3 p-3.5" style={{ background: `${C.green}14`, border: `1.5px solid ${C.green}55`, borderRadius: 16 }}>
              <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: `${C.green}22` }}>
                <Check size={17} color={C.green} />
              </div>
              <p style={fs_(13.5, { color: C.text1, lineHeight: 1.55 })}>
                <b>Já guardei o dinheiro de verdade?</b> Pode marcar o número.
              </p>
            </div>
            <div className="flex items-center gap-3 p-3.5" style={{ background: `${C.danger}12`, border: `1.5px solid ${C.danger}55`, borderRadius: 16 }}>
              <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: `${C.danger}22` }}>
                <X size={17} color={C.danger} />
              </div>
              <p style={fs_(13.5, { color: C.text1, lineHeight: 1.55 })}>
                <b>Ainda não guardei?</b> Não marque. Espere guardar de verdade primeiro.
              </p>
            </div>
          </div>
          <div className="mt-5 p-4" style={{ ...glassActive, borderRadius: 16, border: `1px solid ${C.danger}44` }}>
            <p style={fs_(13, { color: C.text2, lineHeight: 1.65 })}>
              Marcar antes de guardar cria a ilusão de que o dinheiro já está protegido, e é fácil esquecer de completar depois. <b style={{ color: C.text1 }}>Nunca marque um número sem ter guardado o valor antes.</b>
            </p>
          </div>
          <p className="mt-5 font-semibold text-center" style={fs_(14.5, { color: C.text1, lineHeight: 1.6 })}>
            Disciplina e compromisso são o que vão fazer seu cofre ser um sucesso.
          </p>
        </>
      ),
    },
    {
      icon: Flame,
      color: C.amber,
      title: `Seu Cofre escolhido tem ${fmtInt(n)} números`,
      body: (
        <>
          <p style={fs_(14.5, { color: C.text2, lineHeight: 1.75 })}>
            Marcando <b style={{ color: C.text1 }}>1 número por dia</b>, sem pular nenhum dia, é isso que esse cofre te dá:
          </p>
          <div className="mt-5 flex flex-col gap-3">
            <div className="p-4 flex items-center justify-between" style={{ ...glass, borderRadius: 16 }}>
              <div>
                <p style={fs_(11.5, { color: C.text3 })}>Em 6 meses</p>
                <p className="font-bold mt-1" style={fs_(18, { color: C.text1 })}>{fmtBRL(valueByDays(182))}</p>
              </div>
              <Wallet size={22} color={C.blueElectric} />
            </div>
            <div className="p-4 flex items-center justify-between" style={{ ...glass, borderRadius: 16 }}>
              <div>
                <p style={fs_(11.5, { color: C.text3 })}>Em 1 ano</p>
                <p className="font-bold mt-1" style={fs_(18, { color: C.text1 })}>{fmtBRL(valueByDays(365))}</p>
              </div>
              <TrendingUp size={22} color={C.green} />
            </div>
            <div className="p-4 flex items-center justify-between" style={{ ...glassActive, borderRadius: 16 }}>
              <div>
                <p style={fs_(11.5, { color: C.text3 })}>Cofre completo em</p>
                <p className="font-bold mt-1" style={fs_(20, { color: C.text1 })}>{fmtYears(yearsAt1)}</p>
                <p className="mt-0.5" style={fs_(11.5, { color: C.text3 })}>{fmtBRL(total)} guardados</p>
              </div>
              <Flame size={26} color={C.amber} />
            </div>
          </div>
          <div className="mt-4 flex items-center gap-2 px-1">
            <Shield size={13} color={C.danger} />
            <p style={fs_(11.5, { color: C.text3 })}>Lembrete: marque um número só depois de guardar o valor.</p>
          </div>
        </>
      ),
    },
    {
      icon: TrendingUp,
      color: C.green,
      title: "Adiante o tempo",
      body: (
        <>
          <p style={fs_(14.5, { color: C.text2, lineHeight: 1.75 })}>
            Marcar mais de um número por dia acelera bastante. Arrasta pra ver o efeito nesse cofre:
          </p>
          <div className="mt-5">
            <div className="flex items-center justify-between mb-2.5">
              <span style={fs_(12.5, { color: C.text3 })}>Números por dia</span>
              <span className="font-bold" style={fs_(17, { color: C.green })}>{perDay}</span>
            </div>
            <input
              type="range" min={1} max={20} value={perDay}
              onChange={(e) => setPerDay(Number(e.target.value))}
              className="w-full"
              style={{ accentColor: C.green }}
            />
          </div>
          <div className="mt-5 p-4 flex items-center justify-between" style={{ ...glassActive, borderRadius: 16, border: `1px solid ${C.green}55` }}>
            <div>
              <p style={fs_(11.5, { color: C.text3 })}>Cofre completo em</p>
              <p className="font-bold mt-1" style={fs_(20, { color: C.text1 })}>{fmtYears(yearsAtN)}</p>
              <p className="mt-1" style={fs_(11.5, { color: C.text3 })}>{fmtInt(daysAtN)} dias marcando {perDay}/dia</p>
            </div>
            <TrendingUp size={26} color={C.green} />
          </div>
          <div className="mt-3 p-4 flex items-center justify-between" style={{ ...glass, borderRadius: 16 }}>
            <div>
              <p style={fs_(11.5, { color: C.text3 })}>Guardado em 1 ano nesse ritmo</p>
              <p className="font-bold mt-1" style={fs_(18, { color: C.text1 })}>{fmtBRL(valueByDays(365 * perDay))}</p>
            </div>
            <Wallet size={22} color={C.blueElectric} />
          </div>
          <div className="mt-4 flex items-center gap-2 px-1">
            <Shield size={13} color={C.danger} />
            <p style={fs_(11.5, { color: C.text3 })}>Vale pra qualquer ritmo: só marque depois de guardar.</p>
          </div>
        </>
      ),
    },
  ];

  const cur = steps[step];
  const Icon = cur.icon;
  const isLast = step === steps.length - 1;

  return (
    <div className="absolute inset-0 z-50 flex items-end" style={{ background: "rgba(0,0,0,0.68)" }}>
      <div
        className="relative w-full px-7 pt-7 overflow-y-auto no-scrollbar cofre-tour-step"
        style={{
          background: C.surface1, borderTopLeftRadius: 32, borderTopRightRadius: 32,
          maxHeight: "92%", paddingBottom: "calc(env(safe-area-inset-bottom,0px) + 30px)",
          boxShadow: `0 -20px 60px -20px ${cur.color}55`,
        }}
        key={step}
      >
        <div
          className="absolute pointer-events-none transition-all duration-500"
          style={{ top: -40, left: "50%", transform: "translateX(-50%)", width: 260, height: 200, background: `radial-gradient(50% 50% at 50% 0%, ${cur.color}33 0%, transparent 75%)`, borderTopLeftRadius: 32, borderTopRightRadius: 32 }}
        />

        <div className="mx-auto mb-6 rounded-full" style={{ width: 40, height: 4, background: C.strokeActive }} />

        <div className="flex items-center justify-center gap-1.5 mb-7 relative">
          {steps.map((s, i) => (
            <span
              key={i}
              className="rounded-full transition-all"
              style={{
                width: i === step ? 24 : 6, height: 6,
                background: i <= step ? `linear-gradient(90deg, ${s.color}, ${cur.color})` : C.strokeSoft,
                boxShadow: i === step ? `0 0 8px ${cur.color}88` : "none",
              }}
            />
          ))}
        </div>

        <div className="relative w-16 h-16 mx-auto mb-5">
          <span className="cofre-tour-ring" style={{ "--ring-color": `${cur.color}66` }} />
          <span className="cofre-tour-ring" style={{ "--ring-color": `${cur.color}44`, animationDelay: "0.6s" }} />
          <div className="relative w-16 h-16 rounded-full flex items-center justify-center cofre-glow-pulse" style={{ background: `linear-gradient(150deg, ${cur.color}2e, ${cur.color}12)`, border: `1px solid ${cur.color}40`, "--glow-color": `${cur.color}55` }}>
            <Icon size={28} color={cur.color} />
          </div>
        </div>

        <h3 className="font-bold text-center px-2" style={fs_(19, { color: C.text1, lineHeight: 1.4 })}>{cur.title}</h3>
        <div className="mt-5">{cur.body}</div>
        <div className="flex items-center gap-2.5 mt-8">
          {step > 0 && (
            <button onClick={() => setStep((s) => s - 1)} className="py-3.5 px-5 rounded-2xl font-semibold" style={{ ...glass }}>
              <ArrowLeft size={16} color={C.text2} />
            </button>
          )}
          {!isLast ? (
            <button onClick={() => setStep((s) => s + 1)} className="flex-1 py-3.5 rounded-2xl font-semibold flex items-center justify-center gap-2 cofre-glow-pulse relative overflow-hidden cofre-shine-sweep" style={{ ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66` }}>
              Continuar <ArrowRight size={16} />
            </button>
          ) : (
            <button onClick={onFinish} className="flex-1 py-3.5 rounded-2xl font-semibold flex items-center justify-center gap-2 cofre-glow-pulse relative overflow-hidden cofre-shine-sweep" style={{ backgroundImage: `linear-gradient(90deg, ${C.amber} 0%, ${C.gold} 100%)`, color: "#fff", "--glow-color": `${C.gold}88` }}>
              Entendi, vamos começar <Sparkles size={16} />
            </button>
          )}
        </div>
        {!isLast && (
          <button onClick={onClose} className="w-full text-center mt-4" style={fs_(12.5, { color: C.text3 })}>
            Pular introdução
          </button>
        )}
      </div>
    </div>
  );
}

/* =========================================================================
   GOOGLE "G" MARK — lucide-react has no brand icons, so this is a small
   inline SVG of Google's official four-color mark, used only on the
   "Continuar com Google" button.
   ========================================================================= */
function GoogleMark({ size = 18 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 48 48">
      <path fill="#FFC107" d="M43.6 20.5H42V20.4H24v7.2h11.3C33.6 32.1 29.2 35 24 35c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.1 8 3l5.1-5.1C33.9 6 29.2 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.5Z" />
      <path fill="#FF3D00" d="M6.3 14.7l5.9 4.3C13.9 15.5 18.6 12.5 24 12.5c3.1 0 5.8 1.1 8 3l5.1-5.1C33.9 6 29.2 4 24 4c-7.6 0-14.2 4.3-17.7 10.7Z" />
      <path fill="#4CAF50" d="M24 44c5.1 0 9.8-2 13.3-5.2l-6.1-5.2C29.2 35.3 26.7 36 24 36c-5.2 0-9.6-3.3-11.2-8l-6.2 4.8C10 39.6 16.5 44 24 44Z" />
      <path fill="#1976D2" d="M43.6 20.5H42V20.4H24v7.2h11.3c-.8 2.3-2.3 4.3-4.2 5.6l6.1 5.2C40.3 36 44 30.6 44 24c0-1.3-.1-2.7-.4-3.5Z" />
    </svg>
  );
}

/* =========================================================================
   AUTH SCREEN — email/password + Google OAuth via Supabase Auth. Toggles
   between login and sign-up; errors from Supabase are surfaced in Portuguese
   where reasonably mappable, raw otherwise.
   ========================================================================= */
function AuthScreen({ themeName, onToggleTheme }) {
  const [mode, setMode] = useState("login"); // "login" | "signup"
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [info, setInfo] = useState("");

  const friendlyError = (msg) => {
    if (/invalid login credentials/i.test(msg)) return "E-mail ou senha incorretos.";
    if (/user already registered/i.test(msg)) return "Já existe uma conta com esse e-mail. Tenta entrar.";
    if (/password should be at least/i.test(msg)) return "A senha precisa ter pelo menos 6 caracteres.";
    if (/unable to validate email/i.test(msg) || /invalid email/i.test(msg)) return "Digite um e-mail válido.";
    return msg;
  };

  const handleSubmit = async () => {
    setError("");
    setInfo("");
    if (!email.trim() || !password) {
      setError("Preenche e-mail e senha.");
      return;
    }
    setLoading(true);
    const fn = mode === "login" ? supabase.auth.signInWithPassword : supabase.auth.signUp;
    const { error: authError } = await fn.call(supabase.auth, { email: email.trim(), password });
    setLoading(false);
    if (authError) {
      setError(friendlyError(authError.message));
      return;
    }
    if (mode === "signup") setInfo("Conta criada! Entrando...");
  };

  const handleGoogle = async () => {
    setError("");
    setLoading(true);
    const { error: authError } = await supabase.auth.signInWithOAuth({
      provider: "google",
      options: { redirectTo: window.location.origin },
    });
    setLoading(false);
    if (authError) setError(friendlyError(authError.message));
  };

  return (
    <Screen>
      <div className="flex-1 flex flex-col px-7 pb-10 relative overflow-hidden" style={{ paddingTop: "calc(env(safe-area-inset-top,0px) + 56px)" }}>
        <div className="absolute inset-0 aurora-drift pointer-events-none" />
        <button
          onClick={onToggleTheme}
          className="absolute z-10 flex items-center gap-1.5 pl-2.5 pr-3 py-2 rounded-full active:scale-95 transition-transform"
          style={{ top: "calc(env(safe-area-inset-top,0px) + 10px)", right: 20, ...glass }}
        >
          {themeName === "black" ? <Moon size={13} color={C.gold} /> : themeName === "soft" ? <Cloud size={13} color={C.gold} /> : <Sun size={13} color={C.blueElectric} />}
        </button>

        <div className="flex flex-col items-center justify-center relative shrink-0" style={{ paddingTop: 4, paddingBottom: 16 }}>
          <VaultHero size={215} tier={1} img={VAULT_IMG} ring={false} />
          <h1 className="mt-1 font-bold text-center leading-tight" style={fs_(24, { color: C.text1 })}>
            {mode === "login" ? "Bem-vindo de volta" : "Crie sua conta"}
          </h1>
          <p className="mt-1.5 text-center" style={fs_(12.5, { color: C.text3 })}>
            {mode === "login" ? "Entre para continuar guardando" : "Leva menos de um minuto"}
          </p>
        </div>

        <div className="flex flex-col gap-3">
          <div className="flex items-center gap-2.5 p-3.5" style={{ background: C.surface1, borderRadius: 16, border: `1.5px solid ${C.strokeSoft}` }}>
            <Mail size={16} color={C.text3} className="shrink-0" />
            <input
              type="email" autoCapitalize="none" autoCorrect="off" inputMode="email"
              value={email} onChange={(e) => setEmail(e.target.value)}
              placeholder="seu@email.com"
              className="flex-1 bg-transparent outline-none"
              style={fs_(14, { color: C.text1 })}
            />
          </div>
          <div className="flex items-center gap-2.5 p-3.5" style={{ background: C.surface1, borderRadius: 16, border: `1.5px solid ${C.strokeSoft}` }}>
            <Lock size={16} color={C.text3} className="shrink-0" />
            <input
              type={showPassword ? "text" : "password"}
              value={password} onChange={(e) => setPassword(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSubmit()}
              placeholder="Senha"
              className="flex-1 bg-transparent outline-none"
              style={fs_(14, { color: C.text1 })}
            />
            <button onClick={() => setShowPassword((s) => !s)} className="shrink-0">
              {showPassword ? <EyeOff size={16} color={C.text3} /> : <Eye size={16} color={C.text3} />}
            </button>
          </div>

          {error && <p style={fs_(12.5, { color: C.danger })}>{error}</p>}
          {info && <p style={fs_(12.5, { color: C.green })}>{info}</p>}

          <button
            onClick={handleSubmit}
            disabled={loading}
            className="w-full py-4 rounded-2xl font-semibold flex items-center justify-center gap-2 disabled:opacity-60 active:scale-95 transition-transform cofre-glow-pulse relative overflow-hidden cofre-shine-sweep"
            style={fs_(15, { ...ctaGradient, color: "#fff", "--glow-color": `${C.gold}66` })}
          >
            {loading ? "Aguarda..." : mode === "login" ? "Entrar" : "Criar conta"}
          </button>

          <div className="flex items-center gap-3 my-1">
            <div className="flex-1 h-px" style={{ background: C.strokeSoft }} />
            <span style={fs_(11.5, { color: C.text3 })}>ou</span>
            <div className="flex-1 h-px" style={{ background: C.strokeSoft }} />
          </div>

          <button
            onClick={handleGoogle}
            disabled={loading}
            className="w-full py-3.5 rounded-2xl font-semibold flex items-center justify-center gap-2.5 disabled:opacity-60 active:scale-95 transition-transform"
            style={{ ...glass }}
          >
            <GoogleMark size={17} />
            <span style={fs_(14, { color: C.text1 })}>Continuar com Google</span>
          </button>
        </div>

        <button
          onClick={() => { setMode((m) => (m === "login" ? "signup" : "login")); setError(""); setInfo(""); }}
          className="w-full text-center mt-6"
          style={fs_(13, { color: C.text2 })}
        >
          {mode === "login" ? (
            <>Não tem conta? <span style={{ color: C.blueElectric, fontWeight: 600 }}>Criar agora</span></>
          ) : (
            <>Já tem conta? <span style={{ color: C.blueElectric, fontWeight: 600 }}>Entrar</span></>
          )}
        </button>
      </div>
    </Screen>
  );
}

/* =========================================================================
   ROOT APP — fills the whole viewport using 100dvh (not a % height chain,
   so it can't collapse if an ancestor forgets to set a height)
   ========================================================================= */
export default function App() {
  const [authState, setAuthState] = useState({ status: "loading", session: null });
  const hasLoadedRef = useRef(false);
  const saveTimerRef = useRef(null);
  const [pendingVaultStore, setPendingVaultStore] = useState(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setAuthState({ status: data.session ? "signedIn" : "signedOut", session: data.session });
    });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      setAuthState({ status: session ? "signedIn" : "signedOut", session });
    });
    return () => listener.subscription.unsubscribe();
  }, []);

  const resetLocalStateToDefaults = useCallback(() => {
    setScreen("welcome");
    setAvatarUrl(null);
    setThemeName("clean");
    setActiveVaultId("125k");
    setOwnedVaultIds(["125k"]);
    setCustomVaults([]);
    setVaultLabelOverrides({});
    setStreak(0);
    setLevel(1);
    setProtectedToday(0);
    setVisitedMatch(false);
    writeLocal(LS_ONBOARDED_KEY, null);
    writeLocal(LS_AVATAR_KEY, null);
  }, []);

  const prevUserIdRef = useRef(null);
  useEffect(() => {
    const uid = authState.session?.user?.id ?? null;
    if (authState.status === "signedOut" && prevUserIdRef.current) {
      // A real sign-out (not just the initial load) — clear so the next
      // account that logs in on this device never sees leftover state.
      resetLocalStateToDefaults();
    }
    prevUserIdRef.current = uid;
  }, [authState.status, authState.session?.user?.id, resetLocalStateToDefaults]);

  const [screen, setScreen] = useState(() => (readLocal(LS_ONBOARDED_KEY) === "1" ? "home" : "welcome"));
  const [avatarUrl, setAvatarUrl] = useState(() => readLocal(LS_AVATAR_KEY));
  const [themeName, setThemeName] = useState("clean");
  // Mutates the module-level color tokens (C, glass, gradients, vault art)
  // for this theme, synchronously, before anything below reads them. Cheap
  // enough to just do on every render — it's a handful of object literals,
  // no images are (re)loaded since both vault arts are already in memory.
  applyTheme(themeName);
  const THEME_CYCLE = ["clean", "soft", "black"];
  const toggleTheme = useCallback(() => setThemeName((t) => THEME_CYCLE[(THEME_CYCLE.indexOf(t) + 1) % THEME_CYCLE.length]), []);
  const [activeVaultId, setActiveVaultId] = useState("125k");
  const [ownedVaultIds, setOwnedVaultIds] = useState(["125k"]);
  const [customVaults, setCustomVaults] = useState([]);
  const [vaultLabelOverrides, setVaultLabelOverrides] = useState({});
  const [stubLabel, setStubLabel] = useState("");
  const [numberSheet, setNumberSheet] = useState(null);
  const [mimoStatus, setMimoStatus] = useState({});
  const [streak, setStreak] = useState(0);
  const [level, setLevel] = useState(1);
  const [protectedToday, setProtectedToday] = useState(0);
  const [visitedMatch, setVisitedMatch] = useState(false);

  const allVaults = useMemo(
    () => [...CHALLENGES, ...customVaults].map((v) => (vaultLabelOverrides[v.id] ? { ...v, label: vaultLabelOverrides[v.id] } : v)),
    [customVaults, vaultLabelOverrides]
  );
  const vault = useMultiVaultState(activeVaultId, allVaults);

  // Pull this account's saved state down from Supabase the moment a session
  // appears (fresh login or a page reload with an existing session).
  useEffect(() => {
    if (authState.status !== "signedIn" || !authState.session) {
      hasLoadedRef.current = false;
      return;
    }
    hasLoadedRef.current = false;
    let cancelled = false;
    (async () => {
      const { data, error } = await supabase
        .from("user_data")
        .select("data")
        .eq("user_id", authState.session.user.id)
        .single();
      if (cancelled) return;
      const c = !error ? data?.data?.cofre : null;
      if (c) {
        if (c.ownedVaultIds?.length) setOwnedVaultIds(c.ownedVaultIds);
        if (c.activeVaultId) setActiveVaultId(c.activeVaultId);
        if (c.customVaults) setCustomVaults(c.customVaults);
        if (c.vaultLabelOverrides) setVaultLabelOverrides(c.vaultLabelOverrides);
        if (c.themeName) setThemeName(c.themeName);
        if (c.avatarUrl) setAvatarUrl(c.avatarUrl);
        if (typeof c.streak === "number") setStreak(c.streak);
        if (typeof c.level === "number") setLevel(c.level);
        if (c.vaultStore) setPendingVaultStore(c.vaultStore);
        writeLocal(LS_ONBOARDED_KEY, "1");
        setScreen((s) => (s === "welcome" ? "home" : s));
      }
      hasLoadedRef.current = true;
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authState.status, authState.session?.user?.id]);

  // Board progress (protectedSet/partialMap) can only be restored once
  // `allVaults` already includes any restored custom vaults — otherwise
  // hydrateStore has nothing to match a custom vault's id against. Waiting
  // on `customVaults` here guarantees that ordering.
  useEffect(() => {
    if (!pendingVaultStore) return;
    vault.hydrateStore(pendingVaultStore);
    setPendingVaultStore(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pendingVaultStore, customVaults]);

  // Push this account's state back up to Supabase, debounced, any time
  // something worth remembering changes. Gated on hasLoadedRef so we never
  // overwrite a just-loaded account with the app's default local state.
  useEffect(() => {
    if (authState.status !== "signedIn" || !authState.session || !hasLoadedRef.current) return;
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(() => {
      const payload = {
        ownedVaultIds, activeVaultId, customVaults, vaultLabelOverrides,
        themeName, avatarUrl, streak, level,
        vaultStore: vault.serializeStore(),
      };
      supabase
        .from("user_data")
        .upsert({ user_id: authState.session.user.id, data: { cofre: payload } }, { onConflict: "user_id" })
        .then(({ error }) => { if (error) console.error("COFRE save failed:", error.message); });
    }, 1000);
    return () => clearTimeout(saveTimerRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authState.status, ownedVaultIds, activeVaultId, customVaults, vaultLabelOverrides, themeName, avatarUrl, streak, level, vault.protectedTotal]);

  const go = useCallback((next, payload) => {
    if (next === "stub") setStubLabel(payload?.label || "");
    setNumberSheet(null);
    setScreen(next);
    if (next === "home" && !tourShownRef.current) {
      tourShownRef.current = true;
      setTourOpen(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const openNumber = (n, status) => setNumberSheet({ number: n, status });
  const closeNumber = () => setNumberSheet(null);
  const [coinBurstId, setCoinBurstId] = useState(0);
  const handleProtected = (n) => { vault.protectNumber(n); setCoinBurstId((k) => k + 1); setProtectedToday((k) => k + 1); };
  const [tourOpen, setTourOpen] = useState(false);
  const tourShownRef = useRef(false);
  const [lightBurstId, setLightBurstId] = useState(0);

  const handleCreateVault = useCallback((newVault) => {
    setCustomVaults((prev) => [...prev, newVault]);
    setOwnedVaultIds((prev) => (prev.includes(newVault.id) ? prev : [...prev, newVault.id]));
    setActiveVaultId(newVault.id);
    writeLocal(LS_ONBOARDED_KEY, "1");
    go("home");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [go]);

  // Zera tudo — números protegidos, sequência, nível e mimos — como se a
  // pessoa estivesse começando do zero, e leva de volta para o perfil.
  const resetAllProgress = useCallback(() => {
    vault.resetVault();
    setStreak(0);
    setLevel(1);
    setMimoStatus({});
    setProtectedToday(0);
    setVisitedMatch(false);
    go("profile");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [vault, go]);

  return (
    <div style={{ width: "100%", height: "100dvh", minHeight: "100vh", background: C.bgDeep }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');
        * { font-family: 'Inter', sans-serif; box-sizing: border-box; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        @keyframes breathe { 0%,100% { opacity: 0.75; transform: scale(1); } 50% { opacity: 1; transform: scale(1.06); } }
        .cofre-breathe { animation: breathe 4.2s ease-in-out infinite; }
        @keyframes pulseSoft { 0%,100% { box-shadow: 0 0 0 0 rgba(6,164,175,0.35); } 50% { box-shadow: 0 0 0 6px rgba(6,164,175,0); } }
        @keyframes cofrePulse { 0% { opacity: 0.9; transform: scale(0.9);} 100% { opacity: 0; transform: scale(1.7);} }
        .cofre-pulse { animation: cofrePulse 1.8s ease-out infinite; }
        @keyframes badgeBloom { 0%,100% { filter: brightness(1); } 50% { filter: brightness(1.16); } }
        .cofre-badge-bloom { animation: badgeBloom 3.4s ease-in-out infinite; }
        @keyframes auroraDrift { 0% { background-position: 0% 0%, 100% 0%; } 50% { background-position: 20% 30%, 70% 20%; } 100% { background-position: 0% 0%, 100% 0%; } }
        .aurora-drift {
          background-image: radial-gradient(40% 30% at 20% 20%, rgba(6,164,175,0.10), transparent 70%),
                             radial-gradient(40% 30% at 80% 10%, rgba(232,169,61,0.10), transparent 70%);
          background-size: 200% 200%;
          animation: auroraDrift 16s ease-in-out infinite;
        }
        @keyframes sheetRise { from { transform: translateY(100%); } to { transform: translateY(0); } }
        .sheet-rise { animation: sheetRise 0.32s cubic-bezier(.2,.8,.2,1); }

        @keyframes vaultTilt {
          0%, 100% { transform: rotateY(0deg) rotateX(0deg); }
          25% { transform: rotateY(-6deg) rotateX(2deg); }
          75% { transform: rotateY(6deg) rotateX(-2deg); }
        }
        .cofre-vault-tilt { animation: vaultTilt 7s ease-in-out infinite; transform-style: preserve-3d; }

        @keyframes ringSpin { from { transform: rotate(-90deg); } to { transform: rotate(270deg); } }
        .cofre-ring-spin { animation: ringSpin 7s linear infinite; }

        @keyframes popIn {
          0% { opacity: 0; transform: scale(0.7) translateY(6px); }
          70% { opacity: 1; transform: scale(1.05) translateY(0); }
          100% { opacity: 1; transform: scale(1) translateY(0); }
        }
        .cofre-pop-in { animation: popIn 0.4s cubic-bezier(.2,.9,.3,1.3) both; }

        @keyframes sparkleFloat {
          0%, 100% { opacity: 0; transform: translateY(0) scale(0.6); }
          50% { opacity: 1; transform: translateY(-6px) scale(1); }
        }
        .cofre-sparkle { animation: sparkleFloat 1.4s ease-in-out infinite; }

        @keyframes numberFlip {
          0% { opacity: 0.3; transform: rotateX(90deg); }
          100% { opacity: 1; transform: rotateX(0deg); }
        }
        .cofre-number-flip { animation: numberFlip 0.18s ease-out; display: inline-block; }

        @keyframes badgeTilt {
          0%, 100% { transform: rotateY(0deg) rotateX(0deg) translateY(0px); }
          30% { transform: rotateY(-10deg) rotateX(4deg) translateY(-2px); }
          70% { transform: rotateY(10deg) rotateX(-4deg) translateY(-2px); }
        }
        .cofre-badge-3d { animation: badgeTilt 4.5s ease-in-out infinite; transform-style: preserve-3d; }
        @keyframes badgeShine {
          0% { transform: translateX(-120%) rotate(20deg); opacity: 0; }
          8% { opacity: 0.55; }
          22% { opacity: 0; }
          100% { transform: translateX(220%) rotate(20deg); opacity: 0; }
        }
        .cofre-badge-shine {
          position: absolute; inset: 0; pointer-events: none;
          background: linear-gradient(100deg, transparent 40%, rgba(255,255,255,0.65) 50%, transparent 60%);
          animation: badgeShine 3.6s ease-in-out infinite;
        }

        @keyframes screenEnter {
          from { opacity: 0; transform: translateY(6px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .cofre-screen-enter { animation: screenEnter 0.28s ease-out; }

        @keyframes barShimmer {
          0% { background-position: -140px 0; }
          100% { background-position: 140px 0; }
        }
        .cofre-shimmer {
          background-image: linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.35) 50%, rgba(255,255,255,0) 100%);
          background-size: 140px 100%;
          background-repeat: no-repeat;
          animation: barShimmer 2.2s ease-in-out infinite;
        }

        @keyframes spinCycle {
          0% { transform: translateY(0); }
          100% { transform: translateY(-100%); }
        }

        @keyframes coinFall {
          0% { transform: translateY(-8%) rotate(0deg); opacity: 0; }
          8% { opacity: 1; }
          85% { opacity: 1; }
          100% { transform: translateY(112vh) rotate(var(--coin-rot)); opacity: 0; }
        }
        .cofre-coin {
          position: absolute;
          top: 0;
          will-change: transform, opacity;
          animation-name: coinFall;
          animation-timing-function: cubic-bezier(0.35, 0, 0.65, 1);
          animation-fill-mode: forwards;
        }

        @keyframes glowPulse {
          0%, 100% { box-shadow: 0 0 0px 0px var(--glow-color, rgba(232,169,61,0)); }
          50% { box-shadow: 0 0 22px 3px var(--glow-color, rgba(232,169,61,0.45)); }
        }
        .cofre-glow-pulse { animation: glowPulse 2.6s ease-in-out infinite; }

        @keyframes shineSweep {
          0% { transform: translateX(-120%) skewX(-18deg); }
          100% { transform: translateX(220%) skewX(-18deg); }
        }
        .cofre-shine-sweep::after {
          content: "";
          position: absolute;
          top: 0; left: 0; height: 100%; width: 40%;
          background: linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.35) 50%, rgba(255,255,255,0) 100%);
          animation: shineSweep 3.2s ease-in-out infinite;
          pointer-events: none;
        }

        @keyframes tourFadeUp {
          0% { opacity: 0; transform: translateY(10px); }
          100% { opacity: 1; transform: translateY(0); }
        }
        .cofre-tour-step { animation: tourFadeUp 0.35s ease both; }

        @keyframes sparkleTwinkle {
          0% { transform: scale(0) rotate(0deg); opacity: 0; }
          35% { transform: scale(1) rotate(90deg); opacity: 1; }
          100% { transform: scale(0) rotate(180deg); opacity: 0; }
        }
        .cofre-sparkle-dot {
          position: absolute;
          border-radius: 999px;
          animation-name: sparkleTwinkle;
          animation-timing-function: ease-in-out;
          animation-fill-mode: forwards;
          will-change: transform, opacity;
        }

        @keyframes tourRingPulse {
          0% { transform: scale(0.85); opacity: 0.55; }
          100% { transform: scale(1.55); opacity: 0; }
        }
        .cofre-tour-ring {
          position: absolute; inset: 0; border-radius: 999px;
          border: 1.5px solid var(--ring-color, rgba(232,169,61,0.5));
          animation: tourRingPulse 2.4s ease-out infinite;
        }
      `}</style>

      <div className="relative w-full h-full overflow-hidden mx-auto" style={{ background: bgGradient, maxWidth: 480 }}>
        {authState.status === "loading" && (
          <Screen>
            <div className="flex-1 flex flex-col items-center justify-center">
              <VaultHero size={160} tier={1} img={VAULT_IMG} ring={false} />
            </div>
          </Screen>
        )}
        {authState.status === "signedOut" && <AuthScreen themeName={themeName} onToggleTheme={toggleTheme} />}
        {authState.status === "signedIn" && (
          <>
        {screen === "welcome" && <WelcomeScreen onStart={() => go("carousel")} themeName={themeName} onToggleTheme={toggleTheme} />}
        {screen === "carousel" && (
          <ChallengeCarousel
            onChoose={(id, label) => {
              setActiveVaultId(id);
              setOwnedVaultIds((prev) => (prev.includes(id) ? prev : [...prev, id]));
              if (label) setVaultLabelOverrides((prev) => ({ ...prev, [id]: label }));
              writeLocal(LS_ONBOARDED_KEY, "1");
              go("home");
            }}
            onCreateNew={() => go("createVault")}
          />
        )}
        {screen === "home" && <HomeScreen vault={vault} go={go} streak={streak} level={level} themeName={themeName} onToggleTheme={toggleTheme} onOpenTour={() => setTourOpen(true)} allVaults={allVaults} ownedVaultIds={ownedVaultIds} activeVaultId={activeVaultId} onSelectVault={setActiveVaultId} onRenameVault={(id, label) => setVaultLabelOverrides((prev) => ({ ...prev, [id]: label }))} avatarUrl={avatarUrl} />}
        {screen === "board" && <BoardScreen vault={vault} go={go} openNumber={openNumber} />}
        {screen === "journey" && <JourneyScreen vault={vault} go={go} mimoStatus={mimoStatus} setMimoStatus={setMimoStatus} />}
        {screen === "achievements" && <AchievementsScreen go={go} level={level} vault={vault} streak={streak} />}
        {screen === "wealth" && <WealthScreen vault={vault} go={go} />}
        {screen === "mystery" && <MysteryBoxScreen vault={vault} go={go} />}
        {screen === "withdraw" && <WithdrawScreen vault={vault} go={go} />}
        {screen === "wallets" && <WalletsScreen go={go} />}
        {screen === "myVaults" && <MyVaultsScreen go={go} allVaults={allVaults} ownedVaultIds={ownedVaultIds} activeVaultId={activeVaultId} onSelect={setActiveVaultId} vault={vault} />}
        {screen === "createVault" && <CreateVaultScreen go={go} onCreate={handleCreateVault} />}
        {screen === "match" && <MatchScreen vault={vault} go={go} onVisit={() => setVisitedMatch(true)} onProtected={handleProtected} />}
        {screen === "roulette" && <RouletteScreen vault={vault} go={go} onProtected={handleProtected} />}
        {screen === "hunt" && <HuntScreen vault={vault} go={go} openNumber={openNumber} />}
        {screen === "missions" && <MissionsScreen go={go} streak={streak} protectedToday={protectedToday} visitedMatch={visitedMatch} />}
        {screen === "profile" && <ProfileScreen go={go} level={level} vault={vault} streak={streak} onResetProgress={resetAllProgress} themeName={themeName} onSetTheme={setThemeName} avatarUrl={avatarUrl} onSetAvatar={(url) => { setAvatarUrl(url); writeLocal(LS_AVATAR_KEY, url); }} />}
        {screen === "stub" && <StubScreen label={stubLabel} go={go} />}

        {numberSheet && (
          <NumberFlow number={numberSheet.number} status={numberSheet.status} onClose={closeNumber} onProtected={handleProtected} streak={streak} />
        )}

        {coinBurstId > 0 && <CoinRain key={coinBurstId} />}
        {lightBurstId > 0 && <LightBurst key={`lb-${lightBurstId}`} />}

        {tourOpen && (
          <OnboardingTour
            vault={vault}
            onClose={() => setTourOpen(false)}
            onFinish={() => { setLightBurstId((k) => k + 1); setTourOpen(false); }}
          />
        )}
          </>
        )}
      </div>
    </div>
  );
}
